// Auto-generated from the reference workbooks — do not edit by hand.
// These are byte-faithful .xlsx templates: every style, merge, picture and
// page-setup value of the original file is preserved; only the cell text is
// a <Company:*>/<Account:*>/<Data:*>/<Items:*> tag.

export const OUR_INVOICE_B64 =
  "";

export const DC_SEP_B64 =
  "";

export const S_WELDER_B64 =
  "";

export interface InvoiceDesign {
  key: string;
  name: string;
  nameAr: string;
  b64: string;
}

export const INVOICE_DESIGNS: InvoiceDesign[] = [
  { key: "our-invoice", name: "Our Invoice", nameAr: "فاتورتنا", b64: OUR_INVOICE_B64 },
  { key: "dc-sep", name: "DC SEP", nameAr: "دي سي سيب", b64: DC_SEP_B64 },
  { key: "s-welder", name: "S Welder", nameAr: "إس ويلدر", b64: S_WELDER_B64 },
];

export const DEFAULT_DESIGN_KEY = "our-invoice";

export function designByKey(key?: string | null): InvoiceDesign | undefined {
  if (!key) return undefined;
  return INVOICE_DESIGNS.find((d) => d.key === key);
}

// Tenant print lock: a tenant listed here only ever prints that one design —
// the picker hides the others and every PDF/Excel export uses it, whatever the
// invoice or an uploaded template says. Tenants not listed keep the full list.
export const TENANT_DESIGN_LOCK: Record<number, string> = { 15: "dc-sep", 14: "s-welder" };

export function lockedDesignKey(tenantId?: number | null): string | undefined {
  if (tenantId == null) return undefined;
  return TENANT_DESIGN_LOCK[Number(tenantId)];
}

export function designsForTenant(tenantId?: number | null): InvoiceDesign[] {
  const lock = lockedDesignKey(tenantId);
  return lock ? INVOICE_DESIGNS.filter((d) => d.key === lock) : INVOICE_DESIGNS;
}
